import {roi,npv,payback,evm,riskScore,calculateCpm} from '../lib/calculators.mjs';
import {backendConfigured,bootstrapWorkspace,createControlledDocument,createDocumentShare,createProject,downloadControlledDocument,listControlledDocuments,listDocuments,loadWorkspaceContext,reviseControlledDocument,revokeDocumentShare,signOut,signedDocumentUrl,transitionControlledDocument,updateProject,uploadDocument} from './backend.js';
import {bindStudio,loadStudio,renderCommunications,renderIntegrations} from './studio.js';
import {bindTeam,loadTeam,renderTeam} from './team.js';
import {initializeAccount} from './account.js';

const UI_KEY='arkhimar.pm.ui.v1';
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const uid=()=>crypto.randomUUID();
const esc=(value='')=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const num=value=>Number(value)||0;
const today=()=>new Date().toISOString().slice(0,10);
const formatNumber=(value,digits=1)=>value===null||!Number.isFinite(value)?'Not computable':new Intl.NumberFormat(undefined,{maximumFractionDigits:digits}).format(value);
const money=(value,currency='NGN')=>new Intl.NumberFormat(undefined,{style:'currency',currency,maximumFractionDigits:0}).format(num(value));

function audit(project,action,entity,detail){project.audit.unshift({id:uid(),at:new Date().toISOString(),actor:cloud.session.user.email,action,entity,detail});}
function projectModel(raw={}){return{
  id:raw.id||uid(),_version:raw._version||1,_documents:raw._documents??null,_controlledDocuments:raw._controlledDocuments??null,title:raw.title||'',code:raw.code||'',description:raw.description||'',industry:raw.industry||'Other',approach:raw.approach||'Predictive',region:raw.region||'',timezone:raw.timezone||'Africa/Lagos',currency:raw.currency||'NGN',confidentiality:raw.confidentiality||'Internal',problem:raw.problem||'',outcome:raw.outcome||'',objectives:raw.objectives||'',successCriteria:raw.successCriteria||'',benefits:raw.benefits||'',drivers:raw.drivers||'',start:raw.start||'',finish:raw.finish||'',complexity:raw.complexity||'Moderate',priority:raw.priority||'Medium',governance:raw.governance||'Standard stage gates',reporting:raw.reporting||'Weekly',sponsor:raw.sponsor||'',projectManager:raw.projectManager||'',team:raw.team||'',approvalRoles:raw.approvalRoles||'',template:raw.template||'Blank',status:raw.status||'Setup',createdAt:raw.createdAt||new Date().toISOString(),
  business:{executiveSummary:'',recommendedOption:'',estimatedCost:0,estimatedBenefit:0,discountRate:10,cashFlows:'-1000000, 450000, 500000, 550000',status:'Draft',version:1,...raw.business},
  charter:{purpose:'',scope:'',deliverables:'',exclusions:'',milestones:'',budget:'',risks:'',authority:'',status:'Draft',version:1,approvedSnapshot:null,...raw.charter},
  planning:{scope:'',acceptance:'',exclusions:'',assumptions:'',constraints:'',planSummary:'',requirements:[],wbs:[],baseline:null,...raw.planning},
  schedule:{tasks:[],baseline:null,...raw.schedule},cost:{bac:0,pv:0,ev:0,ac:0,contingency:0,reserve:0,items:[],baseline:null,...raw.cost},
  controls:{risks:[],issues:[],changes:[],stakeholders:[],...raw.controls},
  reports:raw.reports||[],audit:raw.audit||[]
}};
let cloud;
try{cloud=await loadWorkspaceContext()}catch(error){
  const target=$('[data-workspace]');
  $('[data-security-context]').textContent='The secure workspace could not finish loading.';
  target.innerHTML=`<header class="page-heading"><div><p>WORKSPACE STARTUP</p><h1>We could not load your workspace.</h1><span>Your signed-in session is safe. Retry the connection or sign out and return later.</span></div></header><section class="panel startup-error" role="alert"><strong>Workspace connection failed</strong><p>${esc(error.message||'An unexpected startup error occurred.')}</p><div class="button-group"><button class="primary" type="button" data-retry-workspace>Retry</button><button class="secondary" type="button" data-startup-signout>Sign out</button></div></section>`;
  $('[data-retry-workspace]').addEventListener('click',()=>location.reload());
  $('[data-startup-signout]').addEventListener('click',signOut);
  await new Promise(()=>{});
}
if(!backendConfigured||!cloud.session){location.replace('/pm/login/');await new Promise(()=>{})}
const canManageProject=['owner','admin','project_manager'].includes(cloud.role);
const canUploadDocument=canManageProject||cloud.role==='member';
const savedUi=(()=>{try{return JSON.parse(sessionStorage.getItem(UI_KEY)||'{}')}catch{return{}}})();
let state={projects:cloud.projects.map(projectModel),activeId:savedUi.activeId||null,view:savedUi.view||'overview'};
if(['communications','integrations'].includes(state.view)&&cloud.workspace){try{await loadStudio(cloud)}catch{state.view='overview'}}
if(state.view==='team'&&cloud.workspace){try{await loadTeam(cloud)}catch{state.view='overview'}}
function save(){sessionStorage.setItem(UI_KEY,JSON.stringify({activeId:state.activeId,view:state.view}));}
function active(){return state.projects.find(project=>project.id===state.activeId)}
const persistQueues=new Map();
function setProject(project){if(!canManageProject){notify('Read-only access','Your workspace role does not permit project changes.');return}const index=state.projects.findIndex(item=>item.id===project.id);state.projects[index]=project;save();render();const prior=persistQueues.get(project.id)||Promise.resolve(),next=prior.then(()=>updateProject(project)).then(()=>{$('[data-security-context]').textContent=`${cloud.workspace.name} · ${cloud.role.replace('_',' ')} · saved securely`}).catch(error=>notify('Save failed',error.message));persistQueues.set(project.id,next)}
function completion(project){const checks=[project.problem,project.outcome,project.sponsor,project.projectManager,project.successCriteria,project.charter.status==='Approved',project.planning.scope,project.planning.requirements.length,project.planning.wbs.length,project.schedule.tasks.length,num(project.cost.bac)>0,project.controls.risks.length,project.governance];return Math.round(checks.filter(Boolean).length/checks.length*100)}
function rag(project){const score=completion(project);const critical=project.controls.risks.filter(r=>riskScore(num(r.probability),num(r.impact))>=16&&r.status!=='Closed').length;return critical||score<45?['At risk','red']:score<75?['Watch','amber']:['On track','green']}
function notify(title,copy){$('[data-notice-title]').textContent=title;$('[data-notice-copy]').textContent=copy;$('[data-notice-dialog]').showModal()}
function heading(project,title,kicker,actions=''){return`<header class="page-heading"><div><p>${esc(kicker)}</p><h1>${esc(title)}</h1>${project?`<span>${esc(project.code)} · ${esc(project.approach)} · ${esc(project.confidentiality)}</span>`:''}</div><div class="heading-actions">${actions}</div></header>`}
function empty(title,copy,button=''){return`<div class="empty-state"><strong>${esc(title)}</strong><p>${esc(copy)}</p>${button}</div>`}
function field(label,name,value='',type='text',extra=''){return`<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function textarea(label,name,value='',extra=''){return`<label class="wide">${esc(label)}<textarea name="${esc(name)}" rows="4" ${extra}>${esc(value)}</textarea></label>`}

function renderHome(){if(!cloud.workspace)return`${heading(null,'Create your secure workspace.','WELCOME TO ARKHIMAR PM')}<section class="panel onboarding-panel"><p>Your first workspace establishes the tenant boundary for projects, members, audit events and private documents.</p><form class="inline-form" data-bootstrap-workspace><input name="name" required minlength="2" maxlength="120" placeholder="Workspace name" aria-label="Workspace name"><button type="submit">Create workspace</button></form></section>`;const projects=state.projects;const average=projects.length?Math.round(projects.reduce((sum,p)=>sum+completion(p),0)/projects.length):0;return`${heading(null,'Good day, Architect.','MY PROJECTS','<button class="primary" type="button" data-new-project>New project <span>＋</span></button>')}
<section class="health-strip"><article><small>Active projects</small><strong>${projects.length}</strong><span>In this workspace</span></article><article><small>Average readiness</small><strong>${average}%</strong><span>Across all projects</span></article><article><small>Approvals</small><strong>${projects.filter(p=>p.charter.status==='Submitted').length}</strong><span>Awaiting decision</span></article><article><small>Open risks</small><strong>${projects.reduce((n,p)=>n+p.controls.risks.filter(r=>r.status!=='Closed').length,0)}</strong><span>Across the portfolio</span></article></section>
<section class="workspace-grid"><article class="panel projects-panel"><header><div><p class="eyebrow">PROJECTS</p><h2>Your control rooms</h2></div><button type="button" data-new-project>＋ Add</button></header><div class="project-list">${projects.length?projects.map(p=>{const health=rag(p);return`<button class="project-row" type="button" data-open-project="${p.id}"><span class="project-mark">${esc(p.code).slice(0,3)}</span><span><strong>${esc(p.title)}</strong><small>${esc(p.code)} · ${esc(p.approach)} · ${esc(p.industry)}</small></span><span class="badge ${health[1]}">${health[0]}</span><span><b>${completion(p)}%</b><small>ready</small></span></button>`}).join(''):empty('No projects yet','Create a project or load the demonstration project to explore every control area.','<button class="secondary" type="button" data-seed>Load demonstration project →</button>')}</div></article>
<aside class="panel next-panel"><p class="eyebrow">RECOMMENDED NEXT</p><div class="readiness-ring" style="--progress:${average}%"><span>${average}%</span></div><h2>Build a reliable foundation</h2><p>Complete project identity, authorization, scope, schedule, budget, risks and governance to improve readiness.</p><button class="secondary" type="button" data-new-project>Start project setup →</button></aside></section>
<section class="panel principles"><p class="eyebrow">OPERATING PRINCIPLES</p><div><article><span>01</span><h3>Connected</h3><p>Plans, registers, baselines and evidence reference the same project truth.</p></article><article><span>02</span><h3>Deterministic</h3><p>Schedule, financial, risk and earned-value arithmetic is calculated and testable.</p></article><article><span>03</span><h3>Accountable</h3><p>Material changes require people, permission and a durable decision trail.</p></article></div></section>`}

function projectNav(project){const [label,color]=rag(project);return`${heading(project,project.title,state.view==='overview'?'PROJECT CONTROL ROOM':state.view.replace(/\b\w/g,c=>c.toUpperCase()),`<button class="secondary" type="button" data-home>All projects</button><span class="health-pill ${color}">${label}</span>`)}`}
function renderOverview(project){const score=completion(project);const items=[['Business need',project.problem,'business'],['Sponsor assigned',project.sponsor,'overview'],['Charter approved',project.charter.status==='Approved','charter'],['Scope defined',project.planning.scope,'planning'],['Requirements recorded',project.planning.requirements.length,'planning'],['WBS created',project.planning.wbs.length,'planning'],['Schedule built',project.schedule.tasks.length,'schedule'],['Budget established',num(project.cost.bac)>0,'schedule'],['Risk register started',project.controls.risks.length,'controls'],['Governance selected',project.governance,'overview']];return`${projectNav(project)}<section class="metric-strip"><article><small>Readiness</small><strong>${score}%</strong><span>Transparent checklist</span></article><article><small>Charter</small><strong>${esc(project.charter.status)}</strong><span>Version ${project.charter.version}</span></article><article><small>Schedule</small><strong>${project.schedule.tasks.length}</strong><span>Activities</span></article><article><small>Risks</small><strong>${project.controls.risks.filter(r=>r.status!=='Closed').length}</strong><span>Open items</span></article></section><div class="content-grid"><section class="panel"><p class="eyebrow">PROJECT READINESS</p><h2>${score}% complete</h2><div class="checklist">${items.map(([label,done,view])=>`<button type="button" data-go="${view}" class="${done?'done':''}"><span>${done?'✓':'○'}</span><b>${label}</b><small>${done?'Complete':'Action needed'} →</small></button>`).join('')}</div></section><aside class="panel detail-list"><p class="eyebrow">PROJECT FRAME</p><dl><div><dt>Problem / opportunity</dt><dd>${esc(project.problem)||'Not defined'}</dd></div><div><dt>Expected outcome</dt><dd>${esc(project.outcome)||'Not defined'}</dd></div><div><dt>Sponsor</dt><dd>${esc(project.sponsor)||'Unassigned'}</dd></div><div><dt>Project manager</dt><dd>${esc(project.projectManager)||'Unassigned'}</dd></div><div><dt>Dates</dt><dd>${esc(project.start)||'TBC'} — ${esc(project.finish)||'TBC'}</dd></div><div><dt>Template</dt><dd>${esc(project.template)}</dd></div></dl></aside></div>`}

function renderBusiness(project){const b=project.business;const flows=String(b.cashFlows||'').split(',').map(num);let financial={roi:null,npv:null,payback:null};try{financial={roi:roi(num(b.estimatedBenefit),num(b.estimatedCost)),npv:npv(num(b.discountRate)/100,flows),payback:payback(flows)}}catch{}return`${projectNav(project)}<div class="content-grid"><form class="panel data-form" data-save="business"><div class="section-title"><div><p class="eyebrow">INITIATION</p><h2>Business case</h2></div><span class="status-chip">${esc(b.status)} · v${b.version}</span></div><div class="form-grid">${textarea('Executive summary','executiveSummary',b.executiveSummary)}${textarea('Recommended option','recommendedOption',b.recommendedOption)}${field('Estimated cost','estimatedCost',b.estimatedCost,'number','min="0"')}${field('Estimated benefits','estimatedBenefit',b.estimatedBenefit,'number','min="0"')}${field('Discount rate (%)','discountRate',b.discountRate,'number','step="0.1" min="0"')}${field('Cash flows by period','cashFlows',b.cashFlows,'text','placeholder="-1000000, 450000, 500000"')}</div><footer><p>Calculations update after saving.</p><button class="primary" type="submit">Save business case</button></footer></form><aside class="panel"><p class="eyebrow">FINANCIAL ANALYSIS</p><div class="analysis-list"><article><small>Simple ROI</small><strong>${financial.roi===null?'Not computable':formatNumber(financial.roi*100)+'%'}</strong></article><article><small>NPV</small><strong>${financial.npv===null?'Not computable':money(financial.npv,project.currency)}</strong></article><article><small>Payback period</small><strong>${financial.payback===null?'Not reached':formatNumber(financial.payback)+' periods'}</strong></article><article><small>Benefit–cost ratio</small><strong>${num(b.estimatedCost)?formatNumber(num(b.estimatedBenefit)/num(b.estimatedCost),2):'Not computable'}</strong></article></div><p class="helper">Assumptions: cash flows occur at period end; the first value is period zero; entered benefits and costs drive ROI.</p></aside></div>`}

function renderCharter(project){const c=project.charter;const locked=c.status==='Approved';return`${projectNav(project)}<form class="panel data-form" data-save="charter"><div class="section-title"><div><p class="eyebrow">AUTHORIZATION</p><h2>Project charter</h2></div><span class="status-chip ${locked?'approved':''}">${esc(c.status)} · v${c.version}</span></div>${locked?'<div class="approved-note">This approved version is immutable. Create a revision to make changes.</div>':''}<div class="form-grid">${textarea('Purpose and justification','purpose',c.purpose,locked?'disabled':'required')}${textarea('High-level scope','scope',c.scope,locked?'disabled':'')}${textarea('Key deliverables','deliverables',c.deliverables,locked?'disabled':'')}${textarea('Out of scope / exclusions','exclusions',c.exclusions,locked?'disabled':'')}${textarea('Summary milestones','milestones',c.milestones,locked?'disabled':'')}${textarea('Summary budget','budget',c.budget,locked?'disabled':'')}${textarea('High-level risks','risks',c.risks,locked?'disabled':'')}${textarea('Project manager authority','authority',c.authority,locked?'disabled':'')}</div><footer><p>Approval records a versioned snapshot and audit event.</p><div class="button-group">${locked?'<button class="secondary" type="button" data-revise-charter>Create revision</button>':'<button class="secondary" type="button" data-submit-charter>Submit for approval</button><button class="primary" type="submit">Save draft</button>'}${c.status==='Submitted'?'<button class="primary" type="button" data-approve-charter>Approve charter</button>':''}</div></footer></form>`}

function renderPlanning(project){const p=project.planning;return`${projectNav(project)}<form class="panel data-form" data-save="planning"><div class="section-title"><div><p class="eyebrow">CORE PLANNING</p><h2>Scope &amp; master plan</h2></div>${p.baseline?`<span class="status-chip approved">Scope baseline v${p.baseline.version}</span>`:''}</div><div class="form-grid">${textarea('Master PM plan summary','planSummary',p.planSummary)}${textarea('Product and project scope','scope',p.scope)}${textarea('Acceptance criteria','acceptance',p.acceptance)}${textarea('Exclusions','exclusions',p.exclusions)}${textarea('Assumptions','assumptions',p.assumptions)}${textarea('Constraints','constraints',p.constraints)}</div><footer><button class="secondary" type="button" data-baseline="scope">${p.baseline?'Create revised baseline':'Approve scope baseline'}</button><button class="primary" type="submit">Save planning data</button></footer></form>
<div class="dual-grid"><section class="panel"><div class="section-title"><div><p class="eyebrow">TRACEABILITY</p><h2>Requirements</h2></div></div><form class="inline-form" data-add="requirement"><input name="description" required placeholder="Requirement description" aria-label="Requirement description"><input name="owner" placeholder="Owner" aria-label="Requirement owner"><select name="priority" aria-label="Priority"><option>Must</option><option>Should</option><option>Could</option></select><button type="submit">Add</button></form>${p.requirements.length?`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Requirement</th><th>Owner</th><th>Priority</th><th></th></tr></thead><tbody>${p.requirements.map((r,i)=>`<tr><td>REQ-${String(i+1).padStart(3,'0')}</td><td>${esc(r.description)}</td><td>${esc(r.owner)||'Unassigned'}</td><td>${esc(r.priority)}</td><td><button class="row-action" data-remove="requirement" data-id="${r.id}" aria-label="Remove requirement">×</button></td></tr>`).join('')}</tbody></table></div>`:empty('No requirements','Add measurable requirements and assign an owner.')}</section>
<section class="panel"><div class="section-title"><div><p class="eyebrow">DECOMPOSITION</p><h2>Work breakdown structure</h2></div></div><form class="inline-form" data-add="wbs"><input name="name" required placeholder="Work package" aria-label="Work package"><input name="owner" placeholder="Owner" aria-label="Owner"><input name="level" type="number" min="1" max="6" value="1" aria-label="Level"><button type="submit">Add</button></form>${p.wbs.length?`<div class="table-wrap"><table><thead><tr><th>WBS</th><th>Work package</th><th>Owner</th><th></th></tr></thead><tbody>${p.wbs.map((w,i)=>`<tr><td>${i+1}.0</td><td style="padding-left:${num(w.level)*10}px">${esc(w.name)}</td><td>${esc(w.owner)||'Unassigned'}</td><td><button class="row-action" data-remove="wbs" data-id="${w.id}" aria-label="Remove work package">×</button></td></tr>`).join('')}</tbody></table></div>`:empty('No work packages','Decompose the approved scope into manageable work.')}</section></div>`}

function scheduleResult(project){try{return calculateCpm(project.schedule.tasks.map(t=>({id:t.id,duration:num(t.duration)})),project.schedule.tasks.filter(t=>t.predecessor).map(t=>({from:t.predecessor,to:t.id})))}catch(error){return{error:error.message,tasks:[],critical:[],duration:0}}}
function renderSchedule(project){const result=scheduleResult(project);const c=project.cost;const metrics=evm({pv:num(c.pv),ev:num(c.ev),ac:num(c.ac),bac:num(c.bac)});return`${projectNav(project)}<div class="dual-grid"><section class="panel"><div class="section-title"><div><p class="eyebrow">SCHEDULE ENGINE</p><h2>Activities &amp; critical path</h2></div><span class="status-chip">${result.error?esc(result.error):`${result.duration} days`}</span></div><form class="inline-form schedule-add" data-add="task"><input name="name" required placeholder="Activity name" aria-label="Activity name"><input name="duration" required type="number" min="0" value="1" aria-label="Duration in days"><select name="predecessor" aria-label="Finish-to-start predecessor"><option value="">No predecessor</option>${project.schedule.tasks.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><button type="submit">Add</button></form>${project.schedule.tasks.length?`<div class="table-wrap"><table><thead><tr><th>Activity</th><th>Duration</th><th>ES–EF</th><th>Float</th><th></th></tr></thead><tbody>${project.schedule.tasks.map(t=>{const calc=result.tasks.find(item=>item.id===t.id);return`<tr class="${result.critical.includes(t.id)?'critical-row':''}"><td>${esc(t.name)}${result.critical.includes(t.id)?'<small> Critical</small>':''}</td><td>${t.duration}d</td><td>${calc?`${calc.es}–${calc.ef}`:'—'}</td><td>${calc?calc.float:'—'}</td><td><button class="row-action" data-remove="task" data-id="${t.id}" aria-label="Remove task">×</button></td></tr>`}).join('')}</tbody></table></div>`:empty('No activities','Add activities and finish-to-start dependencies to calculate the critical path.')}<footer><button class="secondary" type="button" data-baseline="schedule">${project.schedule.baseline?'Revise schedule baseline':'Approve schedule baseline'}</button></footer></section>
<form class="panel data-form" data-save="cost"><div class="section-title"><div><p class="eyebrow">COST CONTROL</p><h2>Budget &amp; earned value</h2></div>${c.baseline?`<span class="status-chip approved">Baseline v${c.baseline.version}</span>`:''}</div><div class="form-grid compact">${field('Budget at completion','bac',c.bac,'number','min="0"')}${field('Contingency reserve','contingency',c.contingency,'number','min="0"')}${field('Management reserve','reserve',c.reserve,'number','min="0"')}${field('Planned value (PV)','pv',c.pv,'number','min="0"')}${field('Earned value (EV)','ev',c.ev,'number','min="0"')}${field('Actual cost (AC)','ac',c.ac,'number','min="0"')}</div><div class="evm-grid"><article><small>CV</small><strong>${money(metrics.cv,project.currency)}</strong></article><article><small>SV</small><strong>${money(metrics.sv,project.currency)}</strong></article><article><small>CPI</small><strong>${formatNumber(metrics.cpi,2)}</strong></article><article><small>SPI</small><strong>${formatNumber(metrics.spi,2)}</strong></article><article><small>EAC</small><strong>${metrics.eac===null?'—':money(metrics.eac,project.currency)}</strong></article><article><small>VAC</small><strong>${metrics.vac===null?'—':money(metrics.vac,project.currency)}</strong></article></div><footer><button class="secondary" type="button" data-baseline="cost">${c.baseline?'Revise cost baseline':'Approve cost baseline'}</button><button class="primary" type="submit">Save cost data</button></footer></form></div>`}

function renderControls(project){const c=project.controls;const register=(title,key,columns)=>`<section class="panel register"><div class="section-title"><div><p class="eyebrow">CONTROL REGISTER</p><h2>${title}</h2></div><span>${c[key].length} records</span></div><form class="inline-form" data-add="${key}">${columns.map(col=>col.type==='select'?`<select name="${col.name}" aria-label="${col.label}">${col.options.map(x=>`<option>${x}</option>`).join('')}</select>`:`<input name="${col.name}" ${col.required?'required':''} ${col.type?`type="${col.type}"`:''} ${col.min?`min="${col.min}"`:''} placeholder="${col.label}" aria-label="${col.label}">`).join('')}<button type="submit">Add</button></form>${c[key].length?`<div class="record-list">${c[key].map(item=>`<article><div><strong>${esc(item.title||item.name)}</strong><p>${Object.entries(item).filter(([k])=>!['id','title','name'].includes(k)).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join(' · ')}</p></div><div>${key==='changes'&&item.status==='Proposed'?`<button class="row-action approve" data-approve-change="${item.id}">Approve</button>`:''}<button class="row-action" data-remove="${key}" data-id="${item.id}" aria-label="Remove record">×</button></div></article>`).join('')}</div>`:empty(`No ${title.toLowerCase()}`,`Add the first ${title.toLowerCase().replace(/s$/,'')} to establish the register.`)}</section>`;return`${projectNav(project)}<div class="control-stack">${register('Risks','risks',[{name:'title',label:'Risk event',required:true},{name:'owner',label:'Owner'},{name:'probability',label:'Probability 1–5',type:'number',min:'1'},{name:'impact',label:'Impact 1–5',type:'number',min:'1'},{name:'status',label:'Status',type:'select',options:['Open','Monitoring','Closed']}])}${register('Issues','issues',[{name:'title',label:'Issue',required:true},{name:'owner',label:'Owner'},{name:'due',label:'Due date',type:'date'},{name:'status',label:'Status',type:'select',options:['Open','In progress','Closed']}])}${register('Change requests','changes',[{name:'title',label:'Change request',required:true},{name:'impact',label:'Scope / schedule / cost impact'},{name:'owner',label:'Decision owner'},{name:'status',label:'Status',type:'select',options:['Proposed','Under review','Rejected']}])}${register('Stakeholders','stakeholders',[{name:'name',label:'Stakeholder',required:true},{name:'role',label:'Role / organisation'},{name:'owner',label:'Engagement owner'},{name:'status',label:'Engagement',type:'select',options:['Unaware','Resistant','Neutral','Supportive','Leading']}])}</div>`}

function renderReports(project){const last=project.reports[0];return`${projectNav(project)}<div class="content-grid"><form class="panel data-form" data-add="report"><div class="section-title"><div><p class="eyebrow">STATUS REPORT</p><h2>Publish a snapshot</h2></div>${last?`<span class="status-chip">Last: ${esc(last.date)}</span>`:''}</div><div class="form-grid">${field('Reporting date','date',today(),'date','required')}${field('Overall status','health',rag(project)[0])}${textarea('Executive summary','summary',last?.summary||'')}${textarea('Achievements this period','achievements','')}${textarea('Next period priorities','next','')}${textarea('Decisions needed','decisions','')}</div><footer><p>Calculated readiness is ${completion(project)}%. Any status override should be explained in the summary.</p><button class="primary" type="submit">Publish status report</button></footer></form><aside class="panel"><p class="eyebrow">EXPORT CENTER</p><h2>Portable project data</h2><p class="helper">Exports use the saved project state and record an audit event. Browser Print can be saved as PDF.</p><div class="export-grid"><button type="button" data-export="json"><b>JSON</b><span>Complete structured backup</span></button><button type="button" data-export="csv"><b>CSV</b><span>Flat control registers</span></button><button type="button" data-export="txt"><b>TXT</b><span>Readable project pack</span></button><button type="button" data-export="print"><b>PDF</b><span>Print current report</span></button></div><h3 class="subheading">Report history</h3>${project.reports.length?`<ol class="history">${project.reports.map(r=>`<li><b>${esc(r.date)} · ${esc(r.health)}</b><span>${esc(r.summary)}</span></li>`).join('')}</ol>`:empty('No reports','Publish the first governed status snapshot.')}</aside></div>`}
function renderAudit(project){return`${projectNav(project)}<section class="panel"><div class="section-title"><div><p class="eyebrow">ACCOUNTABILITY</p><h2>Audit trail</h2></div><span>${project.audit.length} events</span></div>${project.audit.length?`<ol class="audit-list">${project.audit.map(event=>`<li><time datetime="${event.at}">${new Date(event.at).toLocaleString()}</time><div><strong>${esc(event.action)}</strong><p>${esc(event.entity)} · ${esc(event.detail)}</p></div><small>${esc(event.actor)}</small></li>`).join('')}</ol>`:empty('No recorded activity','Material project actions will appear here.')}</section>`}
function controlledActions(document){
  const exports=`<button class="secondary compact-button" type="button" data-export-document="${document.id}" data-format="docx">DOCX</button><button class="secondary compact-button" type="button" data-export-document="${document.id}" data-format="pdf">PDF</button>`;
  if(!canManageProject)return exports;
  if(document.status==='draft')return`${exports}<button class="secondary compact-button" type="button" data-transition-document="${document.id}" data-next-status="in_review">Submit for review</button>`;
  if(document.status==='in_review')return`${exports}${['owner','admin'].includes(cloud.role)?`<button class="primary compact-button" type="button" data-transition-document="${document.id}" data-next-status="approved">Approve</button>`:''}<button class="secondary compact-button" type="button" data-transition-document="${document.id}" data-next-status="draft">Request changes</button>`;
  if(document.status==='approved')return`${exports}<button class="primary compact-button" type="button" data-share-document="${document.id}">Share approved</button>${['owner','admin'].includes(cloud.role)?`<button class="secondary compact-button" type="button" data-transition-document="${document.id}" data-next-status="archived">Archive</button>`:''}<button class="primary compact-button" type="button" data-revise-document="${document.id}">Create revision</button>`;
  return exports;
}
function renderDocuments(project){
  const files=project._documents,documents=project._controlledDocuments;
  const register=documents===null?'<p class="helper">Loading the controlled register…</p>':documents.length?`<div class="controlled-register">${documents.map(document=>{const current=document.versions?.find(version=>version.version===document.current_version),activeShares=(document.shares||[]).filter(share=>!share.revoked_at&&new Date(share.expires_at)>new Date());return`<article><div class="document-code"><strong>${esc(document.document_code)}</strong><span class="status-chip ${document.status}">${esc(document.status.replace('_',' '))}</span></div><div><h3>${esc(document.title)}</h3><p>${esc(document.artifact_type)} · Version ${document.current_version} · ${esc(document.confidentiality)}${document.owner_name?` · Owner: ${esc(document.owner_name)}`:''}</p>${current?.content?.summary?`<p class="document-summary">${esc(current.content.summary)}</p>`:''}<small>${document.versions.length} version${document.versions.length===1?'':'s'} retained · Updated ${new Date(document.updated_at).toLocaleString()}</small>${activeShares.length?`<div class="share-history">${activeShares.map(share=>`<span>${share.format.toUpperCase()} share · ${share.download_count}/${share.max_downloads} downloads · expires ${new Date(share.expires_at).toLocaleString()} <button type="button" data-revoke-share="${share.id}" data-document-id="${document.id}">Revoke</button></span>`).join('')}</div>`:''}</div><div class="document-actions">${controlledActions(document)}</div></article>`}).join('')}</div>`:empty('No controlled documents','Create the first governed project document. Each approved version becomes immutable and remains in the audit history.');
  return`${projectNav(project)}<section class="panel register"><div class="section-title"><div><p class="eyebrow">DOCUMENT CONTROL</p><h2>Controlled document register</h2></div><span>${documents?.length||0} records</span></div>${canManageProject?`<form class="data-form controlled-document-form" data-create-controlled><div class="form-grid compact"><label>Document ID / code *<input name="document_code" required maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9._-]{1,39}" placeholder="AKH-PMP-001"></label><label>Document type *<select name="artifact_type" required><option>Project Charter</option><option>Business Case</option><option>Project Management Plan</option><option>Scope Statement</option><option>Status Report</option><option>Other</option></select></label><label>Title *<input name="title" required maxlength="180"></label><label>Owner<input name="owner_name" maxlength="120" value="${esc(project.projectManager)}"></label><label>Confidentiality<select name="confidentiality"><option>Internal</option><option>Confidential</option><option>Restricted</option><option>Public</option></select></label><label>Tags<input name="tags" placeholder="governance, design, client"></label><label class="wide">Document summary *<textarea name="summary" rows="4" required placeholder="State the controlled content or executive summary for this version."></textarea></label><label class="wide">Revision note<input name="revision_notes" placeholder="Initial issue"></label></div><footer><p>Draft → review → approval. Approved versions cannot be edited.</p><button class="primary" type="submit">Create controlled document</button></footer></form>`:''}${register}</section><section class="panel"><div class="section-title"><div><p class="eyebrow">PRIVATE STORAGE</p><h2>Project file attachments</h2></div><span>${files?.length||0} files</span></div><form class="document-upload" data-document-upload><label>Choose a project file<input type="file" name="document" required accept=".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx,.xls,.xlsx"></label><p>PDF, images, Word or Excel · maximum 10 MB · private by default</p><button class="primary" type="submit">Upload securely</button></form>${files===null?'<p class="helper">Loading authorized files…</p>':files.length?`<div class="record-list">${files.map(doc=>`<article><div><strong>${esc(doc.filename)}</strong><p>${esc(doc.content_type)} · ${(doc.size_bytes/1024/1024).toFixed(2)} MB · ${new Date(doc.created_at).toLocaleString()}</p></div><button class="secondary" type="button" data-open-document="${doc.storage_path}">Open for 60 seconds</button></article>`).join('')}</div>`:empty('No file attachments','Files uploaded here are stored in a private bucket and accessed through short-lived signed URLs.')}</section>`;
}

function render(){
  const project=active(),target=$('[data-workspace]');
  $('[data-project-context]').textContent=project?project.title:'My Projects';
  $('[data-workspace-name]').textContent=cloud.workspace?.name?.toUpperCase()||'SECURE WORKSPACE';
  $('[data-security-context]').textContent=cloud.workspace?`${cloud.workspace.name} · ${cloud.role.replace('_',' ')} · RLS enforced`:'Create a workspace to establish tenant isolation.';
  $$('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===state.view));
  if(state.view==='communications')target.innerHTML=renderCommunications(cloud,state.projects);
  else if(state.view==='integrations')target.innerHTML=renderIntegrations(cloud);
  else if(state.view==='team')target.innerHTML=renderTeam(cloud);
  else if(!project)target.innerHTML=renderHome();
  else{const views={overview:renderOverview,business:renderBusiness,charter:renderCharter,planning:renderPlanning,schedule:renderSchedule,controls:renderControls,documents:renderDocuments,reports:renderReports,audit:renderAudit};target.innerHTML=(views[state.view]||renderOverview)(project)}
  target.focus({preventScroll:true});bindDynamic();
}

function bindDynamic(){
  applyPermissions();
  $('[data-bootstrap-workspace]')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');button.disabled=true;try{await bootstrapWorkspace(new FormData(event.currentTarget).get('name'));location.reload()}catch(error){button.disabled=false;notify('Workspace setup failed',error.message)}});
  $('[data-document-upload]')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,file=form.elements.document.files[0],allowed=['application/pdf','image/jpeg','image/png','image/webp','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];if(!file||file.size>10485760||!allowed.includes(file.type)){notify('File not accepted','Choose a permitted PDF, image, Word or Excel file no larger than 10 MB.');return}const button=form.querySelector('button');button.disabled=true;button.textContent='Uploading…';try{await uploadDocument({workspaceId:cloud.workspace.id,projectId:active().id,userId:cloud.session.user.id,file});active()._documents=await listDocuments(active().id);render();notify('Upload complete',`${file.name} is stored privately for this project.`)}catch(error){notify('Upload failed',error.message)}finally{button.disabled=false;button.textContent='Upload securely'}});
  $('[data-create-controlled]')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type="submit"]'),values=Object.fromEntries(new FormData(form));button.disabled=true;button.textContent='Creating…';try{await createControlledDocument(active().id,values);active()._controlledDocuments=await listControlledDocuments(active().id);render();notify('Document registered',`${values.document_code.toUpperCase()} is ready as a controlled draft.`)}catch(error){button.disabled=false;button.textContent='Create controlled document';notify('Document not created',error.message)}});
  $$('[data-transition-document]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{await transitionControlledDocument(button.dataset.transitionDocument,button.dataset.nextStatus);active()._controlledDocuments=await listControlledDocuments(active().id);render();notify('Document status updated',`The document is now ${button.dataset.nextStatus.replace('_',' ')}.`)}catch(error){button.disabled=false;notify('Status not changed',error.message)}}));
  $$('[data-revise-document]').forEach(button=>button.addEventListener('click',async()=>{const document=active()._controlledDocuments.find(item=>item.id===button.dataset.reviseDocument),current=document?.versions?.find(version=>version.version===document.current_version),summary=prompt('Summary for the new draft version:',current?.content?.summary||'');if(summary===null||!summary.trim())return;const notes=prompt('Revision note (required):','Updated following approved version');if(notes===null||!notes.trim()){notify('Revision note required','Explain what changed before creating the new version.');return}button.disabled=true;try{const version=await reviseControlledDocument(document.id,summary.trim(),notes.trim());active()._controlledDocuments=await listControlledDocuments(active().id);render();notify('Revision created',`${document.document_code} version ${version} is now a draft.`)}catch(error){button.disabled=false;notify('Revision not created',error.message)}}));
  $$('[data-export-document]').forEach(button=>button.addEventListener('click',async()=>{const document=active()._controlledDocuments.find(item=>item.id===button.dataset.exportDocument),format=button.dataset.format;button.disabled=true;button.textContent='Preparing…';try{const {blob,filename}=await downloadControlledDocument(document.id,document.current_version,format),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();URL.revokeObjectURL(url);notify('Export ready',`${document.document_code} version ${document.current_version} was generated as ${format.toUpperCase()}.`)}catch(error){notify('Export failed',error.message)}finally{button.disabled=false;button.textContent=format.toUpperCase()}}));
  $$('[data-share-document]').forEach(button=>button.addEventListener('click',async()=>{const document=active()._controlledDocuments.find(item=>item.id===button.dataset.shareDocument),format=(prompt('Share format: enter PDF or DOCX','PDF')||'').trim().toLowerCase();if(!['pdf','docx'].includes(format)){notify('Unsupported format','Enter PDF or DOCX.');return}const hours=Number(prompt('How many hours should the link remain active?','168'));if(!Number.isInteger(hours)||hours<1||hours>720){notify('Invalid expiry','Choose between 1 and 720 hours.');return}button.disabled=true;try{const share=await createDocumentShare(document.id,document.current_version,format,hours,10);await navigator.clipboard.writeText(share.url);active()._controlledDocuments=await listControlledDocuments(active().id);render();notify('Secure link copied',`The ${format.toUpperCase()} link expires ${new Date(share.expiresAt).toLocaleString()} and allows up to 10 downloads.`)}catch(error){button.disabled=false;notify('Share not created',error.message)}}));
  $$('[data-revoke-share]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{await revokeDocumentShare(button.dataset.documentId,button.dataset.revokeShare);active()._controlledDocuments=await listControlledDocuments(active().id);render();notify('Share revoked','The external link can no longer be used.')}catch(error){button.disabled=false;notify('Share not revoked',error.message)}}));
  $$('[data-open-document]').forEach(button=>button.addEventListener('click',async()=>{const preview=window.open('about:blank','_blank','noopener');try{const url=await signedDocumentUrl(button.dataset.openDocument);if(preview)preview.location=url;else location.href=url}catch(error){preview?.close();notify('File access failed',error.message)}}));
  $$('[data-new-project]').forEach(button=>button.addEventListener('click',openProject));$$('[data-home]').forEach(button=>button.addEventListener('click',goHome));$$('[data-open-project]').forEach(button=>button.addEventListener('click',()=>{state.activeId=button.dataset.openProject;state.view='overview';save();render()}));$$('[data-go]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.go)));$('[data-seed]')?.addEventListener('click',seedDemo);
  $$('[data-save]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();const project=active();const section=form.dataset.save;const values=Object.fromEntries(new FormData(form));Object.assign(project[section],values);audit(project,'Updated',section,`Saved ${section} data`);setProject(project);notify('Saved',`${section[0].toUpperCase()+section.slice(1)} data was queued for secure storage.`)}));
  $$('[data-add]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();const project=active();const type=form.dataset.add;const values=Object.fromEntries(new FormData(form));const item={id:uid(),...values};if(type==='report'){project.reports.unshift(item);audit(project,'Published','status report',`Status report for ${item.date}`)}else if(['requirement','wbs'].includes(type)){project.planning[type==='requirement'?'requirements':'wbs'].push(item);audit(project,'Created',type,item.description||item.name)}else if(type==='task'){if(values.predecessor===item.id){notify('Invalid dependency','An activity cannot depend on itself.');return}project.schedule.tasks.push({...item,duration:num(item.duration)});const check=scheduleResult(project);if(check.error){project.schedule.tasks.pop();notify('Dependency rejected',check.error);return}audit(project,'Created','schedule activity',item.name)}else{project.controls[type].push(item);audit(project,'Created',type,item.title||item.name)}setProject(project)}));
  $$('[data-remove]').forEach(button=>button.addEventListener('click',()=>{const project=active(),type=button.dataset.remove,id=button.dataset.id;if(['requirement','wbs'].includes(type))project.planning[type==='requirement'?'requirements':'wbs']=project.planning[type==='requirement'?'requirements':'wbs'].filter(x=>x.id!==id);else if(type==='task'){project.schedule.tasks=project.schedule.tasks.filter(x=>x.id!==id).map(x=>x.predecessor===id?{...x,predecessor:''}:x)}else project.controls[type]=project.controls[type].filter(x=>x.id!==id);audit(project,'Deleted',type,'Removed a draft record');setProject(project)}));
  $('[data-submit-charter]')?.addEventListener('click',()=>charterAction('Submitted'));$('[data-approve-charter]')?.addEventListener('click',()=>charterAction('Approved'));$('[data-revise-charter]')?.addEventListener('click',()=>charterAction('Draft'));
  $$('[data-baseline]').forEach(button=>button.addEventListener('click',()=>{const project=active(),type=button.dataset.baseline;if(type==='scope'){project.planning.baseline={id:uid(),version:(project.planning.baseline?.version||0)+1,approvedAt:new Date().toISOString(),snapshot:structuredClone({scope:project.planning.scope,requirements:project.planning.requirements,wbs:project.planning.wbs})}}else{project[type].baseline={id:uid(),version:(project[type].baseline?.version||0)+1,approvedAt:new Date().toISOString(),snapshot:structuredClone(project[type])}}audit(project,'Approved',`${type} baseline`,`Created immutable baseline version ${type==='scope'?project.planning.baseline.version:project[type].baseline.version}`);setProject(project)}));
  $$('[data-approve-change]').forEach(button=>button.addEventListener('click',()=>{const project=active(),change=project.controls.changes.find(x=>x.id===button.dataset.approveChange);change.status='Approved';change.decidedAt=new Date().toISOString();audit(project,'Approved','change request',change.title);setProject(project)}));
  $$('[data-export]').forEach(button=>button.addEventListener('click',()=>exportProject(button.dataset.export)));
  bindStudio(cloud,{notify,refresh:async(reload=true)=>{if(reload)await loadStudio(cloud,true);render()}});
  bindTeam(cloud,{notify,refresh:async()=>{await loadTeam(cloud,true);render()}});
}
function applyPermissions(){
  if(!canManageProject){
    $$('[data-new-project],[data-seed],[data-save] input,[data-save] textarea,[data-save] select,[data-save] button,[data-add] input,[data-add] select,[data-add] button,[data-remove],[data-submit-charter],[data-approve-charter],[data-revise-charter],[data-baseline],[data-approve-change],[data-create-controlled] input,[data-create-controlled] textarea,[data-create-controlled] select,[data-create-controlled] button,[data-transition-document],[data-revise-document]').forEach(element=>element.disabled=true);
    const workspace=$('[data-workspace]');
    if(active()&&workspace&&!workspace.querySelector('[data-read-only-note]'))workspace.insertAdjacentHTML('afterbegin',`<p class="permission-note" data-read-only-note>Read-only project access · role: ${esc(cloud.role.replace('_',' '))}</p>`);
  }
  if(!canUploadDocument)$$('[data-document-upload] input,[data-document-upload] button').forEach(element=>element.disabled=true);
}
function charterAction(status){const project=active();if(status==='Submitted'&&!project.charter.purpose){notify('Charter incomplete','Save a purpose and justification before submitting the charter.');return}if(status==='Approved'){project.charter.approvedSnapshot=structuredClone({...project.charter,approvedSnapshot:null});project.status='Authorized'}if(status==='Draft'&&project.charter.status==='Approved'){project.charter.version+=1;project.charter.approvedSnapshot=null}project.charter.status=status;audit(project,status==='Draft'?'Revised':status,'project charter',`Charter version ${project.charter.version}`);setProject(project)}
async function setView(view){const workspaceViews=['communications','integrations','team'];if(workspaceViews.includes(view)&&!cloud.workspace){notify('Create a workspace','Create your secure workspace before opening shared tools.');return}if(!active()&&view!=='overview'&&!workspaceViews.includes(view)){notify('Select a project','Open or create a project before using this control area.');return}state.view=view;save();$('#rail').classList.remove('open');if(['communications','integrations'].includes(view)){render();try{await loadStudio(cloud)}catch(error){notify('Workspace tools unavailable',error.message)}}if(view==='team'){render();try{await loadTeam(cloud)}catch(error){notify('Team unavailable',error.message)}}if(view==='documents'&&(active()._documents===null||active()._controlledDocuments===null)){render();try{const [files,documents]=await Promise.all([active()._documents===null?listDocuments(active().id):active()._documents,active()._controlledDocuments===null?listControlledDocuments(active().id):active()._controlledDocuments]);active()._documents=files;active()._controlledDocuments=documents}catch(error){notify('Documents unavailable',error.message)}}render()}
function goHome(){state.activeId=null;state.view='overview';save();render()}
function exportProject(format){const project=active();let content='',type='text/plain',extension=format;if(format==='json'){content=JSON.stringify({schemaVersion:'arkhimar-pm-project-v1',exportedAt:new Date().toISOString(),project},null,2);type='application/json'}else if(format==='csv'){const rows=[['register','id','title','owner','status'],...project.controls.risks.map(x=>['risk',x.id,x.title,x.owner,x.status]),...project.controls.issues.map(x=>['issue',x.id,x.title,x.owner,x.status]),...project.controls.changes.map(x=>['change',x.id,x.title,x.owner,x.status]),...project.planning.requirements.map(x=>['requirement',x.id,x.description,x.owner,x.priority])];content=rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');type='text/csv'}else if(format==='txt'){content=`ARKHIMAR PM PROJECT PACK\n${project.title} (${project.code})\nGenerated: ${new Date().toISOString()}\nClassification: ${project.confidentiality}\n\nBUSINESS NEED\n${project.problem}\n\nEXPECTED OUTCOME\n${project.outcome}\n\nCHARTER (${project.charter.status} v${project.charter.version})\n${project.charter.purpose}\n\nSCOPE\n${project.planning.scope}\n\nSTATUS\nReadiness: ${completion(project)}%\nRisks: ${project.controls.risks.length}\nIssues: ${project.controls.issues.length}\n` }else{audit(project,'Exported','project report','Opened print/PDF view');save();window.print();return}const blob=new Blob([content],{type:`${type};charset=utf-8`}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`ARKHIMAR_PM_${project.code}_${today()}.${extension}`;link.click();URL.revokeObjectURL(link.href);audit(project,'Exported','project data',format.toUpperCase());save();render()}

function seedDemo(){const p=projectModel({title:'Lagos Civic Learning Hub',code:'AKH-026',description:'A climate-responsive civic learning and community facility.',industry:'Architecture / Construction',approach:'Hybrid',problem:'Limited access to flexible, digitally enabled community learning space.',outcome:'Deliver an inclusive learning hub with measurable community use and energy performance.',objectives:'Expand learning access; demonstrate climate-responsive public architecture',successCriteria:'Practical completion by Q4; 20% energy improvement; client acceptance',benefits:'Higher learning capacity and civic participation',start:'2026-09-14',finish:'2027-06-30',sponsor:'Lagos Civic Foundation',projectManager:'A. Himar',governance:'Standard stage gates',template:'Construction / Architecture'});p.business={...p.business,executiveSummary:'Develop a flexible civic learning hub that combines classrooms, digital access and public gathering space.',recommendedOption:'Phased design-and-build delivery',estimatedCost:480000000,estimatedBenefit:650000000,discountRate:10,cashFlows:'-480000000, 90000000, 130000000, 180000000, 250000000'};p.charter={...p.charter,purpose:p.business.executiveSummary,scope:'Design, approvals, construction, fit-out and operational handover.',deliverables:'Approved design; constructed facility; digital learning fit-out; handover package',milestones:'Design approval; planning approval; structure complete; practical completion',budget:'NGN 480,000,000',risks:'Planning approval delay; material inflation; rainy-season disruption',authority:'Manage approved resources and escalate forecast variances over 10%.',status:'Approved',approvedSnapshot:{version:1},version:1};p.planning.scope=p.charter.scope;p.planning.acceptance='Regulatory approval, snag closure and signed client acceptance.';p.planning.requirements=[{id:uid(),description:'Accessible learning spaces for 200 concurrent users',owner:'Design Lead',priority:'Must'},{id:uid(),description:'20% operational energy improvement against baseline',owner:'Sustainability Lead',priority:'Should'}];p.planning.wbs=[{id:uid(),name:'Design and approvals',owner:'Design Lead',level:1},{id:uid(),name:'Construction',owner:'Site Lead',level:1},{id:uid(),name:'Fit-out and handover',owner:'Project Manager',level:1}];const t1=uid(),t2=uid(),t3=uid(),t4=uid();p.schedule.tasks=[{id:t1,name:'Concept and stakeholder validation',duration:15,predecessor:''},{id:t2,name:'Detailed design and approvals',duration:35,predecessor:t1},{id:t3,name:'Construction and fit-out',duration:140,predecessor:t2},{id:t4,name:'Commissioning and handover',duration:12,predecessor:t3}];p.cost={...p.cost,bac:480000000,pv:120000000,ev:108000000,ac:105000000,contingency:30000000,reserve:20000000};p.controls.risks=[{id:uid(),title:'Planning approval delay affects mobilisation',owner:'Project Manager',probability:3,impact:4,status:'Monitoring'},{id:uid(),title:'Material price escalation exceeds allowance',owner:'Cost Consultant',probability:4,impact:4,status:'Open'}];p.controls.stakeholders=[{id:uid(),name:'Lagos Civic Foundation',role:'Sponsor',owner:'Project Manager',status:'Leading'}];audit(p,'Created','project','Loaded demonstration project');audit(p,'Approved','project charter','Charter version 1');createProject(cloud.workspace.id,p,cloud.session.user.id).then(stored=>Object.assign(p,stored)).catch(error=>notify('Project creation failed',error.message));state.projects.unshift(p);state.activeId=p.id;state.view='overview';save();render()}

const dialog=$('[data-project-dialog]'),projectForm=$('[data-project-form]'),steps=$$('[data-step]');let step=1;
function reviewProject(){const data=Object.fromEntries(new FormData(projectForm));$('[data-project-review]').innerHTML=`<dl><div><dt>Project</dt><dd>${esc(data.title)} (${esc(data.code)})</dd></div><div><dt>Approach</dt><dd>${esc(data.approach)} · ${esc(data.template)}</dd></div><div><dt>Outcome</dt><dd>${esc(data.outcome)}</dd></div><div><dt>Governance</dt><dd>${esc(data.governance)} · ${esc(data.reporting)} reporting</dd></div><div><dt>Accountability</dt><dd>${esc(data.sponsor)||'Sponsor unassigned'} · ${esc(data.projectManager)||'PM unassigned'}</dd></div></dl>`}
function showStep(next){step=next;steps.forEach(el=>el.classList.toggle('active',num(el.dataset.step)===step));$('[data-step-label]').textContent=`${step} OF ${steps.length}`;$('[data-track]').style.width=`${step/steps.length*100}%`;$('[data-back]').disabled=step===1;$('[data-next]').innerHTML=step===steps.length?'Create project <span>＋</span>':'Continue →';$('[data-wizard-status]').textContent='';if(step===6)reviewProject()}
function openProject(){if(!canManageProject){notify('Permission required','Only workspace owners, admins and project managers can create projects.');return}dialog.showModal();showStep(1);syncOtherIndustry();setTimeout(()=>projectForm.elements.title.focus(),50)}
function syncOtherIndustry(){const isOther=projectForm.elements.industry.value==='Other',label=$('[data-other-industry]');label.hidden=!isOther;if(!isOther)projectForm.elements.industryOther.value=''}
$('[data-industry]').addEventListener('change',syncOtherIndustry);
$('[data-back]').addEventListener('click',()=>showStep(Math.max(1,step-1)));$('[data-next]').addEventListener('click',async()=>{const current=steps[step-1],invalid=$$('input,select,textarea',current).find(input=>!input.checkValidity());if(invalid){invalid.reportValidity();$('[data-wizard-status]').textContent='Complete the required fields.';return}if(step<steps.length){showStep(step+1);return}const data=Object.fromEntries(new FormData(projectForm));if(data.start&&data.finish&&data.finish<data.start){$('[data-wizard-status]').textContent='Finish date must be after the start date.';return}if(data.industry==='Other'&&data.industryOther.trim())data.industry=data.industryOther.trim();delete data.industryOther;let project=projectModel(data);audit(project,'Created','project',`Created from ${project.template} template`);const button=$('[data-next]');button.disabled=true;try{project=await createProject(cloud.workspace.id,project,cloud.session.user.id)}catch(error){notify('Project creation failed',error.message);button.disabled=false;return}state.projects.unshift(project);state.activeId=project.id;state.view='overview';save();projectForm.reset();dialog.close();button.disabled=false;render()});
const rail=$('#rail');$('[data-collapse]').addEventListener('click',()=>rail.classList.toggle('collapsed'));$('[data-mobile]').addEventListener('click',event=>{const open=rail.classList.toggle('open');event.currentTarget.setAttribute('aria-expanded',String(open))});$$('[data-view]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view)));$('[data-home]').addEventListener('click',goHome);
const commandDialog=$('[data-command-dialog]'),commandInput=$('[data-command-input]');function commandResults(query=''){const choices=[{label:'Create a project',action:'new'},...state.projects.map(p=>({label:`Open ${p.title}`,id:p.id})),{label:'Return to all projects',action:'home'}].filter(x=>x.label.toLowerCase().includes(query.toLowerCase()));$('[data-command-results]').innerHTML=choices.map((x,i)=>`<li><button type="button" data-command-choice="${x.action||x.id}">${esc(x.label)}${i===0?' <kbd>Enter</kbd>':''}</button></li>`).join('')||'<li><p>No matching project or command.</p></li>';$$('[data-command-choice]').forEach(b=>b.addEventListener('click',()=>{commandDialog.close();if(b.dataset.commandChoice==='new')openProject();else if(b.dataset.commandChoice==='home')goHome();else{state.activeId=b.dataset.commandChoice;state.view='overview';save();render()}}))}function openCommand(){commandResults();commandDialog.showModal();setTimeout(()=>commandInput.focus(),20)}$('[data-command]').addEventListener('click',openCommand);commandInput.addEventListener('input',()=>commandResults(commandInput.value));
$('[data-notifications]').addEventListener('click',()=>notify('Notifications','No new workspace notifications.'));initializeAccount(cloud);
addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openCommand()}if(event.key==='Escape')rail.classList.remove('open')});
render();
